<script setup lang="ts">
import{ref}from'vue';import{useRouter}from'vue-router';import{useAuthStore}from'../stores/auth';import{passwordPolicyError}from'../auth/password-policy';import ApplicationSettings from'../components/ApplicationSettings.vue';import ConnectionPanel from'../components/ConnectionPanel.vue'
const auth=useAuthStore(),router=useRouter(),current=ref(''),next=ref(''),confirm=ref(''),busy=ref(false),error=ref('')
async function change(){error.value='';const issue=passwordPolicyError(next.value);if(issue){error.value=issue;return};if(next.value!==confirm.value){error.value='两次新密码不一致';return};busy.value=true;try{await auth.changePassword(current.value,next.value,confirm.value);current.value='';next.value='';confirm.value='';await router.replace('/login')}catch(e){error.value=e instanceof Error?e.message:'修改失败'}finally{busy.value=false}}
</script>
<template><section class="page-heading"><div><h1>系统设置</h1><p>管理命名模板、缓存和TMDB。部署参数直接编辑 docker-compose.yml。</p></div><div class="heading-actions"><RouterLink class="inline-link" to="/logs">程序日志</RouterLink><RouterLink class="inline-link" to="/data">数据库浏览</RouterLink></div></section><ApplicationSettings/><ConnectionPanel :allowed-kinds="['tmdb']" title="TMDB配置"/><section class="panel section-gap"><div class="panel-title"><h2>管理员账号</h2><span class="muted">{{auth.account?.username}}</span></div><el-alert v-if="error" :title="error" type="error" :closable="false"/><form class="connection-form password-form" @submit.prevent="change"><label for="current-password">当前密码</label><el-input id="current-password" v-model="current" type="password" show-password autocomplete="current-password" :maxlength="512"/><label for="new-password">新密码</label><el-input id="new-password" v-model="next" type="password" show-password autocomplete="new-password" :maxlength="20"/><p class="field-hint">6–20个字符；修改后撤销所有会话。</p><label for="confirm-new-password">确认新密码</label><el-input id="confirm-new-password" v-model="confirm" type="password" show-password autocomplete="new-password" :maxlength="20"/><el-button type="primary" native-type="submit" :loading="busy" :disabled="!current||!next||!confirm">修改密码并重新登录</el-button></form></section><section class="note-panel"><strong>账号恢复由服务器所有者操作</strong><p>在主程序的数据目录创建空 password 文件并重启 app，启动控制台会仅输出一次30分钟有效的临时密码。使用临时密码登录必须设置新密码。此后台不提供找回或创建恢复文件的入口。</p><p>Docker未挂载的宿主目录无法访问；不要公开挂载宿主根目录、Docker Socket或数据库数据卷。</p></section></template>
<style scoped>.password-form{max-width:500px}.note-panel p{line-height:1.8}</style>
